      taskRole: new iam.Role(this, 'TaskExecutionRole', {
        assumedBy: new iam.ServicePrincipal('ecs-tasks.amazonaws.com'),
      }),
      containerDefinitions: [
        {
          image: 'nginx:latest',
          essential: true,
          name: 'nginx',
          ports: [
            {
              containerPort: 80,
              hostPort: 80,
            },
          ],
        },
      ],
    });

    // Создаем ECS сервис
    const service = new ecs.Service(this, 'ECSService', {
      cluster,
      taskDefinition,
      desiredCount: 1,
      placement: {
        // Если требуется, можно добавить ограничения на размещение
      },
      // Если требуется, можно добавить loadBalancer
      // loadBalancer: new ec2.LoadBalancer(this, 'ALB', { ... }),
    });

    // (Optional) Grant permissions to ECS to pull from ECR
    ecrRepository.grantPull(service.taskDefinition.taskRole);
  }
}

// Использование стека
const app = new cdk.App();
new ECSStack(app, 'ECSStack');
